# Using pytest-benchmark for micro-benchmarks
import pytest

def fibonacci(n):
    return n if n <= 1 else fibonacci(n-1) + fibonacci(n-2)

def test_fibonacci_performance(benchmark):
    result = benchmark(fibonacci, 10)
    assert result == 55
